  background: rgba(240, 232, 212, 0.06);
  font-family: var(--sans);
  font-size: 10px;
  color: var(--cream);
}
.note { font-size: 12px !important; opacity: 0.6; font-style: italic; }

/* ---------------- Touch controls ---------------- */

.touch {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 18;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 max(18px, env(safe-area-inset-left)) max(16px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-right));
  pointer-events: none;
}
.touch-cluster { display: flex; align-items: flex-end; gap: 10px; pointer-events: auto; }
.tbtn {
  width: 66px;
  height: 66px;
  border-radius: 50%;
  border: 1px solid rgba(240, 232, 212, 0.24);
  background: rgba(6, 17, 12, 0.48);
  backdrop-filter: blur(5px);
  color: rgba(240, 232, 212, 0.86);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  font-size: 25px;
  line-height: 1;
  touch-action: none;
  transition: background 0.12s, transform 0.12s;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.24);
}
.tbtn span {
  font-size: 7.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
  margin-top: 2px;
}
.tbtn:active, .tbtn.on {
  background: rgba(156, 194, 127, 0.34);
  transform: scale(0.94);
}
.tbtn.dir { width: 62px; height: 62px; font-size: 32px; }
.tbtn.jump { width: 78px; height: 78px; background: rgba(110, 154, 97, 0.25); border-color: rgba(190, 220, 160, 0.4); }
.tbtn.action { border-color: rgba(232, 181, 106, 0.45); color: var(--amber-hot); }
.tbtn.small { width: 56px; height: 56px; font-size: 17px; }

/* Portrait phones: game above, controls below */

@media (orientation: portrait) and (max-width: 900px) {
  #stage { height: 58dvh; flex: none; margin-top: max(4px, env(safe-area-inset-top)); }
  #app { justify-content: flex-start; }
  .touch {
    position: fixed;
    top: calc(58dvh + 8px);
    bottom: auto;
    height: calc(42dvh - 8px);
    align-items: center;
    padding-top: 10px;
    background: linear-gradient(180deg, transparent, rgba(4, 12, 8, 0.5) 30%);
  }
  .touch-cluster { gap: 14px; }
  .tbtn { width: 74px; height: 74px; }
  .tbtn.dir { width: 76px; height: 68px; font-size: 36px; }
  .tbtn.jump { width: 88px; height: 88px; }
  .tbtn.small { width: 62px; height: 62px; font-size: 19px; }
  .dialogue { bottom: 14px; width: calc(100% - 24px); padding: 12px 13px 14px; }
  .dlg-portrait { width: 40px; height: 40px; font-size: 19px; }
  .dlg-text { font-size: 14.5px; }
  .prompt { bottom: 14px; font-size: 11.5px; padding: 7px 11px; }
  .objective { top: 64px; font-size: 10px; padding: 5px 10px; max-width: 90vw; }
  #hud { font-size: 11px; padding: 10px; }
  .hud-left { top: 10px; left: 12px; gap: 5px; }
  .hud-right { top: 8px; right: 10px; gap: 6px; }
  .icon-btn { width: 32px; height: 32px; }
  .icon-btn svg { width: 15px; height: 15px; }
  #location-label { font-size: 16px; }
  .hud-center { top: 12px; }
  .title-copy { align-self: flex-start; padding-top: 10vh; }
  .title-copy h1 { font-size: clamp(54px, 17vw, 100px); }
  .title-mark { width: 280px; height: 280px; right: -80px; bottom: 4%; opacity: 0.6; }
  .title-foot { display: none; }
  .journal-list { grid-template-columns: 1fr; max-height: 46vh; }
  .how-grid { grid-template-columns: 1fr; gap: 10px; }
  .intro-count { font-size: 32px; }
  .title-screen { background: linear-gradient(180deg, rgba(4, 12, 8, 0.7), rgba(4, 12, 8, 0.9)); }
}

@media (orientation: landscape) and (max-height: 520px) {
  .dialogue { bottom: 12px; width: min(620px, calc(100% - 240px)); padding: 10px 14px; }
