/* Keyboard + touch input, mapped to a tiny set of actions. */

const KEYMAP = {
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ArrowUp: 'jump', KeyW: 'jump', Space: 'jump',
  KeyQ: 'switch', Tab: 'switch', ShiftLeft: 'switch', ShiftRight: 'switch',
  KeyE: 'action', Enter: 'action',
  KeyX: 'strike', KeyK: 'strike',
  KeyJ: 'journal',
  Escape: 'pause', KeyP: 'pause',
  KeyM: 'mute',
};

export class Input {
  constructor() {
    this.down = new Set();
    this.just = new Set();
    this.virtual = new Set();
    this.onFirstGesture = null;
    this._gestured = false;

    window.addEventListener('keydown', (e) => {
      const a = KEYMAP[e.code];
      if (!a) return;
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(e.code)) e.preventDefault();
      this.gesture();
      if (e.repeat) return;
      this.down.add(a);
      this.just.add(a);
    }, { passive: false });

    window.addEventListener('keyup', (e) => {
      const a = KEYMAP[e.code];
      if (!a) return;
      this.down.delete(a);
    });

    window.addEventListener('blur', () => {
      this.down.clear();
      this.virtual.clear();
      document.querySelectorAll('.tbtn.on').forEach((b) => b.classList.remove('on'));
    });

    document.querySelectorAll('[data-input]').forEach((btn) => {
      const action = btn.dataset.input;
      const press = (e) => {
        e.preventDefault();
        this.gesture();
        btn.setPointerCapture?.(e.pointerId);
        this.virtual.add(action);
        this.just.add(action);
        btn.classList.add('on');
      };
      const release = (e) => {
        e.preventDefault();
        this.virtual.delete(action);
        btn.classList.remove('on');
      };
      btn.addEventListener('pointerdown', press, { passive: false });
      btn.addEventListener('pointerup', release, { passive: false });
      btn.addEventListener('pointercancel', release, { passive: false });
      btn.addEventListener('lostpointercapture', release);
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
    });
  }

  gesture() {
    if (this._gestured) return;
    this._gestured = true;
    this.onFirstGesture?.();
  }

  isDown(a) { return this.down.has(a) || this.virtual.has(a); }
  pressed(a) { return this.just.has(a); }
  axis() { return (this.isDown('right') ? 1 : 0) - (this.isDown('left') ? 1 : 0); }
  endFrame() { this.just.clear(); }
}

/* Procedural painterly renderer. Every texture is drawn at runtime. */

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash(n) {
  n = Math.sin(n * 127.1) * 43758.5453;
  return n - Math.floor(n);
}

function rr(ctx, x, y, w, h, r) {
  const q = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + q, y);
  ctx.arcTo(x + w, y, x + w, y + h, q);
  ctx.arcTo(x + w, y + h, x, y + h, q);
  ctx.arcTo(x, y + h, x, y, q);
  ctx.arcTo(x, y, x + w, y, q);
  ctx.closePath();
}

