import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const URL = 'http://localhost:3002/?test=1';
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(OUT, { recursive: true });

let failures = 0;
const check = (name, ok, detail = '') => {
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);
};
const near = (a, b, tol) => Math.abs(a - b) <= tol;

const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, timeout: 45000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('requestfailed', (r) => errors.push('requestfailed: ' + r.url()));

await page.goto(URL, { waitUntil: 'load' });
await page.waitForFunction(() => !!window.__greenBetween, null, { timeout: 15000 });

await page.evaluate(() => {
  const g = window.__greenBetween;
  window.__t = {
    g,
    stop() { g.loop = () => {}; },
    init(levelIndex) {
      g.loop = () => {};
      g.save = { started: true, level: levelIndex, memories: [], completed: false, totalTime: 0, deaths: 0 };
      g.totalTime = 0;
      g.startLevel(levelIndex);
      g.triggerFired.add('intro');
      g.ui.closeDialogue();
      g.dialogueQueue = [];
      g.levelTime = 0;
      g.particles = [];
      g.shake = 0;
    },
    tp(x, groundY) {
      const p = g.player;
      const feet = groundY == null ? g.level.groundY : groundY;
      p.x = x - p.w / 2;
      p.y = feet - p.h;
      p.vx = 0; p.vy = 0;
      p.onGround = true;
      p.invuln = 0;
      p.jumpsLeft = p.char === 'mira' ? 2 : 1;
      g.snapCamera();
    },
    tpWorld(x, y) {
      const p = g.player;
      p.x = x; p.y = y; p.vx = 0; p.vy = 0;
      g.snapCamera();
    },
    step(n = 1) {
      for (let i = 0; i < n; i++) { g.update(1 / 120); g.input.endFrame(); }
    },
    tap(a) { g.input.just.add(a); g.update(1 / 120); g.input.endFrame(); },
    hold(a) { g.input.down.add(a); },
    release(a) { g.input.down.delete(a); },
    drain() {
      let guard = 0;
      while (g.ui.dialogueActive && guard++ < 300) {
        g.ui.updateDialogue(20);
        g.advanceDialogue();
      }
      guard = 0;
      while (g.dialogueQueue.length && guard++ < 10) {
        g.pumpDialogue();
        let inner = 0;
        while (g.ui.dialogueActive && inner++ < 300) {
          g.ui.updateDialogue(20);
          g.advanceDialogue();
        }
      }
      return { active: g.ui.dialogueActive, queue: g.dialogueQueue.length };
    },
    render() { g.renderer.render(1 / 60); },
    item(type, pred = () => true) {
      return g.level.interactables.find((it) => it.type === type && pred(it));
    },
    char(name) {
      if (g.player.char !== name) g.switchCharacter();
      return g.player.char;
    },
  };
});

const T = (fn, arg) => page.evaluate(fn, arg);
const t = (name, ...args) => page.evaluate(({ name, args }) => window.__t[name](...args), { name, args });

/* ---------------------------------------------------------------- */
/* 1. Title, intro, flow into gameplay                              */
/* ---------------------------------------------------------------- */
const titleState = await T(() => ({
  titleVisible: !document.getElementById('screen-title').classList.contains('hidden'),
  continueHidden: document.getElementById('btn-continue').classList.contains('hidden'),
  game: !!window.__greenBetween,
}));
check('title screen visible on load', titleState.titleVisible);
check('new game offered when no save', titleState.continueHidden);

await page.click('#btn-new');
const intro = await T(() => ({
  state: window.__greenBetween.state,
  title: document.getElementById('intro-title').textContent,
  slide: window.__greenBetween.introSlide,
}));
check('new journey opens intro', intro.state === 'intro' && intro.slide === 0, intro.title);

await page.click('#btn-intro-next');
await page.click('#btn-intro-next');
await page.click('#btn-intro-next');
const interlude = await T(() => ({
  state: window.__greenBetween.state,
  title: document.getElementById('interlude-title').textContent,
  text: document.getElementById('interlude-text').textContent.length,
  stats: document.getElementById('interlude-stats').textContent,
}));
check('intro leads to Larkspur interlude', interlude.state === 'interlude' && interlude.title === 'Larkspur');
check('interlude copy and stats render', interlude.text > 20 && !/NAN/i.test(interlude.stats), interlude.stats);

await page.click('#btn-interlude-go');
const started = await T(() => {
  const g = window.__greenBetween;
  return { state: g.state, level: g.level.id, hud: !document.getElementById('hud').classList.contains('hidden') };
});
check('Larkspur starts', started.state === 'playing' && started.level === 'larkspur' && started.hud);

/* Stop the raf loop; from here we drive the simulation deterministically. */
await T(() => { window.__greenBetween.loop = () => {}; window.__greenBetween.ui.closeDialogue(); window.__greenBetween.dialogueQueue = []; });

/* ---------------------------------------------------------------- */
/* 2. Physics                                                       */
/* ---------------------------------------------------------------- */
const walk = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(140, 760);
  const x0 = T.g.player.x;
  T.hold('right'); T.step(120); T.release('right');
  const x1 = T.g.player.x;
  const vx = T.g.player.vx;
  return { dx: x1 - x0, vx, onGround: T.g.player.onGround };
});
check('running 1s covers ground', walk.dx > 260 && walk.dx < 340, `dx=${walk.dx.toFixed(1)}`);
check('player stays grounded', walk.onGround);

const jump = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(1000, 760);
  const startY = T.g.player.y;
  T.hold('jump');
  T.g.input.just.add('jump');
  let minY = startY;
  for (let i = 0; i < 150; i++) {
    T.g.update(1 / 120); T.g.input.endFrame();
    minY = Math.min(minY, T.g.player.y);
  }
  T.release('jump');
  return { rise: startY - minY, landed: T.g.player.onGround };
});
check('single jump height ~105px', near(jump.rise, 105, 14), `rise=${jump.rise.toFixed(1)}`);

const doubleJump = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(1000, 760);
  const startY = T.g.player.y;
  T.hold('jump');
  T.g.input.just.add('jump');
  let minY = startY;
  let doubled = false;
  for (let i = 0; i < 260; i++) {
    T.g.update(1 / 120); T.g.input.endFrame();
    minY = Math.min(minY, T.g.player.y);
    if (!doubled && T.g.player.vy > -30) {
      T.g.input.just.add('jump');
      T.g.update(1 / 120); T.g.input.endFrame();
      doubled = true;
      minY = Math.min(minY, T.g.player.y);
    }
  }
  T.release('jump');
  return { rise: startY - minY };
});
check('double jump reaches ~184px', doubleJump.rise > 160 && doubleJump.rise < 205, `rise=${doubleJump.rise.toFixed(1)}`);

const teoJump = await T(() => {
  const T = window.__t;
  T.init(0);
  T.char('teo');
  T.tp(1000, 760);
  const startY = T.g.player.y;
  T.hold('jump');
  T.g.input.just.add('jump');
  let minY = startY;
  for (let i = 0; i < 200; i++) {
    T.g.update(1 / 120); T.g.input.endFrame();
    minY = Math.min(minY, T.g.player.y);
    if (T.g.player.vy > -20) { T.g.input.just.add('jump'); T.g.update(1 / 120); T.g.input.endFrame(); }
  }
  T.release('jump');
  return { rise: startY - minY, char: T.g.player.char };
});
check('Teo has only a single jump', teoJump.char === 'teo' && teoJump.rise < 130, `rise=${teoJump.rise.toFixed(1)}`);

/* ---------------------------------------------------------------- */
/* 3. Larkspur systems                                              */
/* ---------------------------------------------------------------- */
const rubble = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(1780, 760);
  T.char('mira');
  T.tap('action');
  const denied = !T.item('rubble').cleared;
  T.char('teo');
  T.tap('action');
  return { denied, cleared: T.item('rubble').cleared, char: T.g.player.char };
});
check('rubble requires Teo', rubble.denied && rubble.cleared);

const terminal = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(2360, 760);
  T.char('teo');
  T.tap('action');
  const denied = !T.g.level.interactables.find((i) => i.type === 'gate').open;
  T.char('mira');
  T.tap('action');
  const term = T.item('terminal');
  const gate = T.g.level.interactables.find((i) => i.type === 'gate');
  return { denied, on: term.on, gate: gate.open };
});
check('terminal requires Mira and opens gate', terminal.denied && terminal.on && terminal.gate);

const shard = await T(() => {
  const T = window.__t;
  T.init(0);
  const s = T.g.level.shards[0];
  T.g.player.x = s.x + s.w / 2 - T.g.player.w / 2;
  T.g.player.y = s.y + s.h / 2 - T.g.player.h / 2;
  T.step(2);
  return { collected: s.collected, saved: T.g.save.memories.includes(s.memory), count: T.g.save.memories.length };
});
check('memory shard pickup persists', shard.collected && shard.saved && shard.count === 1);

const checkpoint = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(1180, 760);
  T.step(3);
  const cp = T.g.level.checkpoints[0];
  return { active: cp.active, respawnX: T.g.respawnPoint.x };
});
check('checkpoint activates and updates respawn', checkpoint.active && checkpoint.respawnX === 1170, `x=${checkpoint.respawnX}`);

const larkspurEnd = await T(() => {
  const T = window.__t;
  T.init(0);
  T.tp(4896, 200);
  T.tap('action');
  const dialog = T.g.ui.dialogueActive;
  T.drain();
  return {
    dialog,
    state: T.g.state,
    saveLevel: T.g.save.level,
    screen: !document.getElementById('screen-complete').classList.contains('hidden'),
    shards: document.getElementById('complete-shards').textContent,
  };
});
check('beacon dialogue then chapter complete', larkspurEnd.dialog && larkspurEnd.state === 'complete' && larkspurEnd.screen);
check('completing Larkspur advances save to Vireo', larkspurEnd.saveLevel === 1, `level=${larkspurEnd.saveLevel}`);

/* ---------------------------------------------------------------- */
/* 4. Vireo                                                         */
/* ---------------------------------------------------------------- */
const vireoDeny = await T(() => {
  const T = window.__t;
  T.init(1);
  T.tp(5196, 240);
  T.tap('action');
  return { state: T.g.state, dialog: T.g.ui.dialogueActive, hasCap: T.g.hasCapacitor };
});
check('Vireo beacon refuses without capacitor', vireoDeny.state === 'playing' && !vireoDeny.dialog && !vireoDeny.hasCap);

const vireoCap = await T(() => {
  const T = window.__t;
  T.init(1);
  T.tp(3300, 520);
  T.step(3);
  return { hasCap: T.g.hasCapacitor, objective: document.getElementById('objective-text').textContent };
});
check('capacitor pickup works and updates objective', vireoCap.hasCap && /control tower/i.test(vireoCap.objective), vireoCap.objective);

const vireoFlow = await T(() => {
  const T = window.__t;
  T.init(1);
  T.tp(1850, 770);
  T.char('teo'); T.tap('action');
  const cleared = T.item('rubble').cleared;
  T.tp(2010, 770);
  T.char('mira'); T.tap('action');
  const gate = T.g.level.interactables.find((i) => i.type === 'gate').open;
  T.char('teo'); T.tp(1000, 770);
  T.step(120);
  const fell = T.g.deaths > 0 && T.g.respawnTimer > 0;
  T.step(150);
  const respawned = T.g.respawnTimer === 0 && T.g.player.onGround;
  T.tp(3300, 520); T.step(3);
  T.tp(5196, 240); T.tap('action'); T.drain();
  return { cleared, gate, fell, respawned, state: T.g.state, saveLevel: T.g.save.level, deaths: T.g.deaths };
});
check('Vireo rubble and gate', vireoFlow.cleared && vireoFlow.gate);
check('water fall respawns at checkpoint', vireoFlow.fell && vireoFlow.respawned, `deaths=${vireoFlow.deaths}`);
check('Vireo beacon completes chapter', vireoFlow.state === 'complete' && vireoFlow.saveLevel === 2, `level=${vireoFlow.saveLevel}`);

/* ---------------------------------------------------------------- */
/* 5. Cinder Heights: radiation, enemies, ending                    */
/* ---------------------------------------------------------------- */
const radiation = await T(() => {
  const T = window.__t;
  T.init(2);
  T.char('teo');
  T.tp(4280, 780);
  T.step(40);
  const teoHp = T.g.health;
  T.char('mira');
  T.tp(4280, 780);
  T.step(40);
  const miraHp = T.g.health;
  return { teoHp, miraHp };
});
check('Teo shrugs off radiation', radiation.teoHp === 3, `hp=${radiation.teoHp}`);
check('Mira is hurt by radiation', radiation.miraHp < 3, `hp=${radiation.miraHp}`);

const strike = await T(() => {
  const T = window.__t;
  T.init(0);
  const e = T.g.level.enemies.find((en) => en.type === 'drone');
  const p = T.g.player;
  p.x = e.x - 80; p.y = 560; p.facing = 1;
  T.g.snapCamera();
  T.tap('strike'); T.step(20);
  T.tap('strike'); T.step(20);
  return { hp: e.hp, alive: e.alive };
});
check('strikes defeat a drone', !strike.alive && strike.hp <= 0, `hp=${strike.hp}`);

const cinderEnd = await T(() => {
  const T = window.__t;
  T.init(2);
  T.tp(1750, 780); T.char('teo'); T.tap('action');
  const rubble = T.item('rubble').cleared;
  T.tp(2470, 780); T.char('mira'); T.tap('action');
  const gate = T.g.level.interactables.find((i) => i.type === 'gate').open;
  T.tp(4440, 150); T.tap('action');
  const dialog = T.g.ui.dialogueActive;
  T.drain();
  return {
    rubble, gate, dialog,
    state: T.g.state,
    completed: T.g.save.completed,
    screen: !document.getElementById('screen-ending').classList.contains('hidden'),
    shards: document.getElementById('ending-shards').textContent,
    deaths: document.getElementById('ending-deaths').textContent,
  };
});
check('Cinder rubble and gate', cinderEnd.rubble && cinderEnd.gate);
check('final beacon reaches ending', cinderEnd.dialog && cinderEnd.state === 'ending' && cinderEnd.screen);
check('save marked complete', cinderEnd.completed);

/* ---------------------------------------------------------------- */
/* 6. Persistence, journal, pause                                   */
/* ---------------------------------------------------------------- */
const persisted = await T(() => {
  const raw = JSON.parse(localStorage.getItem('gb.save.v1'));
  return { completed: raw.completed, level: raw.level, memories: raw.memories.length };
});
check('localStorage save persists completion', persisted.completed);

await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.__greenBetween, null, { timeout: 15000 });
const afterReload = await T(() => ({
  continueHidden: document.getElementById('btn-continue').classList.contains('hidden'),
  title: !document.getElementById('screen-title').classList.contains('hidden'),
}));
check('completed save offers a fresh start', afterReload.title && afterReload.continueHidden);

const pauseJournal = await T(() => {
  const g = window.__greenBetween;
  g.loop = () => {};
  g.save = { started: true, level: 0, memories: ['lark_yellow_door'], completed: false, totalTime: 0, deaths: 0 };
  g.startLevel(0);
  g.triggerFired.add('intro'); g.ui.closeDialogue(); g.dialogueQueue = [];
  const shard = g.level.shards[0];
  shard.collected = true;
  g.health = 2;
  g.pauseGame();
  const paused = g.state === 'paused' && !document.getElementById('screen-pause').classList.contains('hidden');
  g.openJournal('paused');
  const journal = g.state === 'journal' && !document.getElementById('screen-journal').classList.contains('hidden');
  const cards = document.querySelectorAll('.memory-card').length;
  const unlocked = document.querySelectorAll('.memory-card:not(.locked)').length;
  g.closeJournal();
  const backToPause = g.state === 'paused';
  g.resumeGame();
  const resumed = g.state === 'playing';
  g.openJournal('playing');
  g.closeJournal();
  return { paused, journal, cards, unlocked, backToPause, resumed, final: g.state };
});
check('pause and journal screens work', pauseJournal.paused && pauseJournal.journal && pauseJournal.backToPause && pauseJournal.resumed);
check('journal lists all 12 memories with unlocked ones', pauseJournal.cards === 12 && pauseJournal.unlocked === 1, `cards=${pauseJournal.cards} unlocked=${pauseJournal.unlocked}`);

const restart = await T(() => {
  const g = window.__greenBetween;
  g.levelTime = 99;
  g.restartLevel();
  return { state: g.state, x: g.player.x, time: g.levelTime < 1 };
});
check('restart chapter resets position and timer', restart.state === 'playing' && restart.x < 200 && restart.time);

/* ---------------------------------------------------------------- */
/* 7. Mobile layout and touch controls                              */
/* ---------------------------------------------------------------- */
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(350);
const mobile = await T(() => {
  const g = window.__greenBetween;
  g.save = { started: true, level: 0, memories: [], completed: false, totalTime: 0, deaths: 0 };
  g.startLevel(0);
  g.triggerFired.add('intro'); g.ui.closeDialogue(); g.dialogueQueue = [];
  g.renderer.render(1 / 60);
  return {
    touchHidden: document.getElementById('touch').classList.contains('hidden'),
    stageH: document.getElementById('stage').getBoundingClientRect().height,
    w: innerWidth, h: innerHeight,
    canvasW: document.getElementById('game').width,
    canvasH: document.getElementById('game').height,
  };
});
check('touch controls visible on phone width', !mobile.touchHidden, `stage=${mobile.stageH.toFixed(0)}`);
check('phone canvas has sane backing size', mobile.canvasW > 300 && mobile.canvasH > 200, `${mobile.canvasW}x${mobile.canvasH}`);
await page.screenshot({ path: join(OUT, 'final-mobile.png') });

const touchSim = await T(() => {
  const g = window.__greenBetween;
  g.loop = () => {};
  const x0 = g.player.x;
  g.input.virtual.add('right');
  for (let i = 0; i < 90; i++) { g.update(1 / 120); g.input.endFrame(); }
  g.input.virtual.delete('right');
  return { dx: g.player.x - x0 };
});
check('virtual touch input moves the player', touchSim.dx > 100, `dx=${touchSim.dx.toFixed(1)}`);

/* ---------------------------------------------------------------- */
/* 8. Screenshots                                                   */
/* ---------------------------------------------------------------- */
await page.setViewportSize({ width: 1280, height: 800 });
await page.waitForTimeout(250);
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => !!window.__greenBetween, null, { timeout: 15000 });
await T(() => {
  const g = window.__greenBetween;
  g.loop = () => {};
  g.renderer.render(1 / 60);
});
await page.screenshot({ path: join(OUT, 'final-title.png') });

for (const [index, name] of [[0, 'final-larkspur'], [1, 'final-vireo'], [2, 'final-cinder']]) {
  await T((idx) => {
    const g = window.__greenBetween;
    g.loop = () => {};
    g.save = { started: true, level: idx, memories: [], completed: false, totalTime: 0, deaths: 0 };
    g.startLevel(idx);
    g.triggerFired.add('intro');
    g.ui.closeDialogue();
    g.dialogueQueue = [];
    // Put the player at an attractive, representative spot and let camera settle.
    const spots = {
      0: [1250, 760],
      1: [140, 770],
      2: [650, 780],
    };
    const [x, y] = spots[idx];
    g.player.x = x; g.player.y = y - g.player.h; g.player.vx = 0; g.player.vy = 0;
    g.partner.x = x - 40; g.partner.y = g.player.y + g.player.h - g.partner.h;
    g.trail = [{ x, y, t: g.levelTime }];
    g.snapCamera();
    g.particles = [];
    for (let i = 0; i < 3; i++) g.renderer.render(1 / 60);
  }, index);
  await page.waitForTimeout(120);
  await page.screenshot({ path: join(OUT, name + '.png') });
}

await T(() => {
  const g = window.__greenBetween;
  g.save = { started: true, level: 2, memories: ['lark_yellow_door', 'vir_flood', 'cin_seed'], completed: true, totalTime: 512, deaths: 4 };
  g.lastStats = { shards: 3, time: 512, deaths: 4 };
  g.state = 'ending';
  g.ui.showEnding(g.lastStats);
  g.renderer.render(1 / 60);
});
await page.waitForTimeout(120);
await page.screenshot({ path: join(OUT, 'final-ending.png') });

/* ---------------------------------------------------------------- */
/* 9. Error collection                                              */
/* ---------------------------------------------------------------- */
check('no page errors', errors.length === 0, errors.slice(0, 5).join(' | '));
console.log('\n' + (failures === 0 ? 'ALL CHECKS PASSED' : `${failures} CHECK(S) FAILED`));

await browser.close();
process.exit(failures === 0 ? 0 : 1);

