import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true });
const page = await browser.newPage({ viewport: { width: 1100, height: 800 } });
page.on('pageerror', (e) => console.log('ERR', e.message));
await page.goto('http://localhost:3002/?debug=1', { waitUntil: 'load' });
await page.waitForFunction(() => !!window.__greenBetween);

const out = await page.evaluate(() => {
  const g = window.__greenBetween;
  g.loop = () => {};
  g.save = { started: true, level: 1, memories: [], completed: false, totalTime: 0, deaths: 0 };
  g.startLevel(1);
  g.triggerFired.add('intro');
  g.ui.closeDialogue();
  g.dialogueQueue = [];
  const p = g.player;
  p.x = 1805 - p.w / 2; p.y = 770 - p.h; p.vx = 0; p.vy = 0;
  g.snapCamera();
  const before = { x: p.x, y: p.y, char: p.char, dlg: g.ui.dialogueActive };
  g.switchCharacter();
  const afterSwitch = { x: p.x, y: p.y, char: p.char, dlg: g.ui.dialogueActive, trigger: [...g.triggerFired] };
  const rubble = g.level.interactables.find((i) => i.type === 'rubble');
  const zone = { x: rubble.x - 46, y: rubble.y - 36, w: rubble.w + 92, h: rubble.h + 72 };
  const near = g.nearbyInteractable();
  g.input.just.add('action');
  g.update(1 / 120);
  g.input.endFrame();
  const afterTap = {
    char: g.player.char, dlg: g.ui.dialogueActive, queue: g.dialogueQueue.length,
    cleared: rubble.cleared, x: g.player.x, y: g.player.y,
    near: near && near.type, trigger: [...g.triggerFired],
  };
  // drain and try again from just left of the rubble
  while (g.ui.dialogueActive) { g.ui.updateDialogue(20); g.advanceDialogue(); }
  g.dialogueQueue = [];
  g.player.x = 1735 - g.player.w / 2; g.player.y = 770 - g.player.h;
  const near2 = g.nearbyInteractable();
  g.input.just.add('action');
  g.update(1 / 120);
  g.input.endFrame();
  const second = { near: near2 && near2.type, cleared: rubble.cleared, dlg: g.ui.dialogueActive, x: g.player.x };

  // terminal
  g.player.x = 2360 - g.player.w / 2; g.player.y = 770 - g.player.h;
  g.player.char = 'mira'; g.player.w = 30; g.player.h = 60; g.player.x = 2360 - 15; g.player.y = 770 - 60;
  while (g.ui.dialogueActive) { g.ui.updateDialogue(20); g.advanceDialogue(); }
  g.dialogueQueue = [];
  g.triggerFired.add('terminal'); g.triggerFired.add('beam');
  const term = g.level.interactables.find((i) => i.type === 'terminal');
  const gate = g.level.interactables.find((i) => i.type === 'gate');
  const nearT = g.nearbyInteractable();
  g.input.just.add('action');
  g.update(1 / 120);
  g.input.endFrame();
  const termAfter = { near: nearT && nearT.type, on: term.on, gate: gate.open, dlg: g.ui.dialogueActive, char: g.player.char };
  return { before, afterSwitch, zone, afterTap, second, termAfter };
});
console.log(JSON.stringify(out, null, 2));
await browser.close();

